  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Calculates the final price of a booking after reward evaluation.
   * A fixed 20 percent discount applies only when the customer owns a membership package
   * containing the DISCOUNTS award and the booking is made at least 24 hours before departure.
   * Both bookingTime and the trip's departureTime are datetime strings in the format yyyy-MM-dd HH:mm,
   * and the 24-hour threshold is computed as the actual duration between the two datetimes
   * (inclusive of the exact 24-hour boundary).
   * The returned amount shall keep one decimal place.
   * When the customer, membership package, booking time, or reward condition is invalid or missing,
   * the original trip price shall be returned.
   * Algorithm:
   *   1. If customer is null or customer.membershipPackage is null or bookingTime is null, return this.price.
   *   2. If customer.membershipPackage.hasAward(DISCOUNTS) is false, return this.price.
   *   3. Parse bookingTime and this.departureTime as datetime strings.
   *   4. Compute difference = departureTime - bookingTime in hours.
   *   5. If difference < 24 hours, return this.price.
   *   6. discountedPrice = this.price * 0.8
   *   7. Return discountedPrice rounded to one decimal place.
   * Related Features: price, departureTime
   * Related Classes: Customer, MembershipPackage, Award
   * Input: customer : Customer - the customer making the booking; bookingTime : String - the booking datetime in yyyy-MM-dd HH:mm format
   * Output: double - the discounted price (one decimal place) or original price
   * Pre-condition: Trip object exists with price and departureTime set.
   * Post-condition: No state change.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public double calculateDiscountedPrice(final Customer customer, final String bookingTime)
  {
    // Step 1: If customer is null or customer.membershipPackage is null or bookingTime is null, return this.price.
    if (customer == null || customer.getMembershipPackage() == null || bookingTime == null) {
      return getPrice();
    }
    
    // Step 2: If customer.membershipPackage.hasAward(DISCOUNTS) is false, return this.price.
    if (!customer.getMembershipPackage().hasAward(Award.DISCOUNTS)) {
      return getPrice();
    }
    
    // Step 3: Parse bookingTime and this.departureTime as datetime strings.
    SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm");
    try {
      Date bookingDate = sdf.parse(bookingTime);
      Date departureDate = sdf.parse(getDepartureTime());
      
      // Step 4: Compute difference = departureTime - bookingTime in hours.
      long diffMillis = departureDate.getTime() - bookingDate.getTime();
      double diffHours = diffMillis / (1000.0 * 60 * 60);
      
      // Step 5: If difference < 24 hours, return this.price.
      if (diffHours < 24.0) {
        return getPrice();
      }
      
      // Step 6: discountedPrice = this.price * 0.8
      double discountedPrice = getPrice() * 0.8;
      
      // Step 7: Return discountedPrice rounded to one decimal place.
      return Math.round(discountedPrice * 10) / 10.0;
      
    } catch (ParseException e) {
      return getPrice();
    }
  }

